const input=$json.body ?? $json;
const deal=input.deal ?? input;
const agreement=input.agreement ?? {};
const buyer=input.buyer ?? {};
const property=input.property ?? {};
const closing=input.closing ?? {};
const dates=input.critical_dates ?? {};
const docs=input.documents ?? {};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const requiredDocs=Array.isArray(docs.required)?docs.required:[];
const suppliedDocs=Array.isArray(docs.supplied)?docs.supplied:[];
const missingDocs=requiredDocs.filter(d=>!suppliedDocs.includes(d));
const openBlockers=blockers.filter(b=>b&&b.resolved!==true&&b.status!=='resolved');
const agreementType=String(agreement.type||deal.agreement_type||'').toLowerCase();
const validAgreement=['assignment','novation','double_close'].includes(agreementType);
const executed=agreement.execution_state==='executed'||deal.execution_state==='executed';
const transactionReady=input.transaction_ready===true||input.status==='ready';
const identityReady=Boolean((deal.id||deal.deal_id)&&(property.id||property.property_id)&&(buyer.id||buyer.buyer_id));
const closingDate=dates.closing_date||closing.closing_date||null;
const assignmentDeadline=dates.assignment_deadline||closing.assignment_deadline||null;
const criticalDate=closingDate||assignmentDeadline||dates.termination_date||null;
const dateState=criticalDate?'present':'missing';
const closingRequirements=Array.isArray(closing.requirements)?closing.requirements:[];
const missingClosingRequirements=closingRequirements.filter(r=>r&&r.required===true&&r.completed!==true);
const titleReady=closing.title_status==='clear'||closing.title_status==='approved'||closing.title_ready===true;
const attorneyReady=closing.attorney_ready===true||closing.attorney_status==='ready';
const buyerFundingReady=closing.buyer_funding_ready===true||closing.funding_status==='verified';
const packageReady=executed&&validAgreement&&transactionReady&&identityReady&&missingDocs.length===0&&missingClosingRequirements.length===0&&openBlockers.length===0&&criticalDate!==null;
const closingReady=packageReady&&titleReady&&attorneyReady&&buyerFundingReady;
let route='human_review';
if(closingReady) route='closing_coordination';
else if(!packageReady) route='closing_package_blocked';
else if(!titleReady) route='title_readiness';
else if(!attorneyReady) route='attorney_readiness';
else if(!buyerFundingReady) route='buyer_funding_readiness';
return [{json:{workflow_id:'WF-135',workflow_name:'Transaction Readiness → Closing Package & Critical-Date Controller',status:closingReady?'ready':packageReady?'package_ready':'blocked',route,transaction_ready:transactionReady,closing_ready:closingReady,deal_id:deal.id??deal.deal_id??null,lead_id:deal.lead_id??null,property_id:property.id??property.property_id??null,buyer_id:buyer.id??buyer.buyer_id??null,agreement_type:agreementType||null,agreement_execution_state:agreement.execution_state??deal.execution_state??null,critical_dates:{closing_date:closingDate,assignment_deadline:assignmentDeadline,termination_date:dates.termination_date??null,date_state:dateState},missing_documents:missingDocs,missing_closing_requirements:missingClosingRequirements,open_blockers:openBlockers,title_ready:titleReady,attorney_ready:attorneyReady,buyer_funding_ready:buyerFundingReady,closing_package:{required_documents:requiredDocs,supplied_documents:suppliedDocs,missing_documents:missingDocs,requirements:closingRequirements},next_workflow:closingReady?'WF-126 closing coordination & critical date controller':route==='title_readiness'?'title/attorney coordination':route==='attorney_readiness'?'attorney readiness':'human_review',crm_activity:{event_type:'transaction_readiness_closing_package',outcome:closingReady?'closing_ready':packageReady?'package_ready':'blocked',route,deal_id:deal.id??deal.deal_id??null},idempotency_key:'wf-135:transaction-readiness-closing-package:'+(deal.id??deal.deal_id??input.event_id??'unknown')}}}];
